func TestReferenceBitwiseNonIntegralSignatures(t *testing.T) {
	p := newReferenceScenario(t)
	p.step(t, referenceExec("CREATE TABLE one(n NUMERIC,r REAL,d DOUBLE PRECISION,bo BOOLEAN,tx TEXT,o OID)", 0))
	p.step(t, referenceExec("INSERT INTO one VALUES(1,1,1,true,'x',1),(NULL,NULL,NULL,NULL,NULL,NULL)", 2))
	for _, tc := range referenceBitwiseSignatureCases {
		s := referenceImplicitError(tc.q, referenceDiagnostic{Code: tc.code, Message: tc.message, Position: tc.pos, Hint: tc.hint})
		s.selectRows = true
		s.errorStage = "execute"
		p.step(t, s)
		s.errorStage = "prepare"
		p.step(t, referencePrepared(s))
	}
}
